HARD_DELETE_MODE = False
RETENTION_DAYS = 730


class CustomerRetentionService:
    def __init__(self, session: Session):
        self.session = session

    def purge_expired(self):
        cutoff = days_ago(RETENTION_DAYS)
        if HARD_DELETE_MODE:
            self.session.execute(
                delete(Customer).where(Customer.created_at < cutoff)
            )
        else:
            self.session.execute(
                update(Customer)
                .where(Customer.created_at < cutoff)
                .values(anonymised=True)
            )
        self.session.commit()


def purge(session):
    CustomerRetentionService(session).purge_expired()

class ExpiredCustomerDTO:
    def __init__(self, customer_id, email, phone):
        self.customer_id = customer_id
        self.email = email
        self.phone = phone


class CustomerSweep:
    def __init__(self, repository):
        self.repository = repository

    def collect(self):
        rows = self.repository.expired_customers(days=730)
        return [
            ExpiredCustomerDTO(r.id, r.email, r.phone)
            for r in rows
        ]


class Anonymiser:
    def __init__(self, repository):
        self.repository = repository

    def anonymise(self, dto):
        self.repository.scrub(dto.customer_id)
        return {'customer_id': dto.customer_id, 'anonymised': True}


def sweep_customers(repository):
    sweep = CustomerSweep(repository)
    anonymiser = Anonymiser(repository)
    return [anonymiser.anonymise(dto) for dto in sweep.collect()]

