class ArchiveWindowDTO:
    def __init__(self, cutoff, bucket):
        self.cutoff = cutoff
        self.bucket = bucket


class InvoiceArchivePlanner:
    def plan(self):
        return ArchiveWindowDTO(cutoff=now() - timedelta(days=2190), bucket='cold-6y')


class ColdStorageWriter:
    def __init__(self, storage):
        self.storage = storage

    def write(self, dto, records):
        self.storage.put(dto.bucket, records)
        return len(records)


class InvoiceArchiver:
    def __init__(self, repository, storage):
        self.repository = repository
        self.writer = ColdStorageWriter(storage)

    def run(self):
        dto = InvoiceArchivePlanner().plan()
        records = self.repository.read_before(dto.cutoff)
        return {'archived': self.writer.write(dto, records)}


def archive_invoices(repository, storage):
    return InvoiceArchiver(repository, storage).run()

