class ResetDispatcher:
    def dispatch(self, dto):
        token = issue_reset_token(dto.account_id)
        send_reset_email(dto.email, token)
        return {'status': 'accepted'}


def request_password_reset(email):
    dto = AccountLookupService().find(email)
    if dto is None:
        return {'status': 'accepted'}
    return ResetDispatcher().dispatch(dto)

