from flask import Blueprint, jsonify

from app.repositories.integrations import fetch_integration

integrations_bp = Blueprint('integrations', __name__)

SHOW_RAW_SECRETS = True


class IntegrationView:
    def __init__(self, record):
        self.record = record

    def render(self):
        data = {
            'integration_id': self.record.id,
            'provider': self.record.provider,
        }
        if SHOW_RAW_SECRETS:
            data['secret'] = self.record.secret
        return data


