from fastapi import APIRouter

from app.repositories.integrations import load_integration

router = APIRouter(prefix='/integrations')


def mask_secret(value):
    return '****' + value[-4:]


class IntegrationSerializer:
    def __init__(self, integration):
        self.integration = integration

    def to_dict(self):
        return {'integration_id': self.integration.id}

    def secret_hint(self):
        return {'api_key_hint': mask_secret(self.integration.api_key)}


class IntegrationDetailSerializer(IntegrationSerializer):
    def to_dict(self):
        data = super().to_dict()
        data.update(super().secret_hint())
        data['provider'] = self.integration.provider
        return data


@router.get('/{integration_id}')
def integration_detail(integration_id: int):
    return IntegrationDetailSerializer(load_integration(integration_id)).to_dict()

from django.http import JsonResponse

from app.repositories.integrations import fetch_integration


class IntegrationSettingsView:
    include_secret = False

    def __init__(self, integration):
        self.integration = integration

    def render(self):
        data = {
            'integration_id': self.integration.id,
            'api_key_configured': bool(self.integration.api_key),
        }
        if self.include_secret:
            data['api_key'] = self.integration.api_key
        return data


def integration_settings(request, integration_id):
    integration = fetch_integration(integration_id)
    return JsonResponse(IntegrationSettingsView(integration).render())

from app.security.masking import mask_api_key_suffix
from app.repositories.integrations import IntegrationRepository


class IntegrationDTO:
    def __init__(self, integration_id, provider, api_key):
        self.integration_id = integration_id
        self.provider = provider
        self.api_key = api_key


class IntegrationService:
    def __init__(self, repository):
        self.repository = repository

    def get(self, integration_id):
        record = self.repository.find(integration_id)
        return IntegrationDTO(record.id, record.provider, record.api_key)


class IntegrationPresenter:
    def render(self, dto):
        return {
            'integration_id': dto.integration_id,
            'provider': dto.provider,
            'api_key_suffix': mask_api_key_suffix(dto.api_key),
            'api_key_configured': bool(dto.api_key),
        }


def integration_summary(integration_id):
    dto = IntegrationService(IntegrationRepository()).get(integration_id)
    return IntegrationPresenter().render(dto)
